interfaces.description:
List of network interfaces to enable NDP proxy on. Each entry configures one interface.
      items: {
        "name": {
          "type": "string",
          "default": "",
          "description": "Name of the interface (e.g., eth0, br-lan). Required."
        },
        "enabled": {
          "type": "bool",
          "default": true,
          "description": "Whether NDP proxy is active on this interface. Set to false to disable."
        }
      }
    }

prefixes.description:
List of IPv6 prefixes to announce via NDP proxy (i.e., respond to neighbor solicitations for).
      items: {
        "address": {
          "type": "string",
          "default": "",
          "description": "IPv6 address of the prefix (e.g., 2001:db8:1::). Required."
        },
        "length": {
          "type": "number",
          "default": 64,
          "description": "Prefix length in bits (typically 64 for subnets)."
        },
        "interface": {
          "type": "string",
          "default": "",
          "description": "Interface through which to proxy replies for this prefix (e.g., br-lan). Required."
        },
        "enabled": {
          "type": "bool",
          "default": true,
          "description": "Whether this prefix is actively proxied. Set to false to disable."
        }
      }
    }
